import '../models/lesson_model.dart'; import '../services/firestore_service.dart'; class LessonRepository { final FirestoreService service; LessonRepository({FirestoreService? service}):service=service??FirestoreService(); Stream<List<LessonModel>> watch(String courseId)=>service.stream('lessons').map((s)=>s.docs.map((d)=>LessonModel.fromMap(d.id,d.data())).where((x)=>x.courseId==courseId).toList()..sort((a,b)=>a.order.compareTo(b.order))); Future<void> save(LessonModel x)=>service.setDoc('lessons',x.id,x.toMap()); }